<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard - School Manager</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f7f9fc;color:#172033}header{padding:24px 7%;background:#172033;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:18px;padding:40px 7%}.card{background:white;border-radius:12px;padding:24px;box-shadow:0 4px 18px #0000000d}.value{font-size:30px;font-weight:700}</style></head><body><header><h1>School Administration</h1><p>Dashboard foundation for managing the school website and records.</p></header><section class="grid"><div class="card"><div class="value">0</div><div>Students / Applications</div></div><div class="card"><div class="value">KES 0</div><div>Total Payments</div></div><div class="card"><div class="value">0</div><div>Pending Payments</div></div><div class="card"><div class="value">0</div><div>Recent Enquiries</div></div><div class="card"><div class="value">0</div><div>Upcoming Events</div></div><div class="card"><div class="value">0</div><div>Announcements</div></div></section></body></html>
